const blogUrl = "https://www.jkdmm.in";

/* =========================
   LOAD JSONP
========================= */

function loadFeed(url, callbackName) {
  const s = document.createElement("script");
  s.src = url + "&callback=" + callbackName;
  document.body.appendChild(s);
}

/* =========================
   EXTRACT LAST DATE
========================= */

function getLastDateObj(post) {

  let text = "";

  if (post.content && post.content.$t) {
    text = post.content.$t;
  } else if (post.summary && post.summary.$t) {
    text = post.summary.$t;
  } else {
    text = post.title.$t;
  }

  text = text.replace(/<[^>]*>/g, " ");

  let match = text.match(/([0-9]{1,2})[.\-/]([0-9]{1,2})[.\-/]([0-9]{4})/);

  if (!match) return null;

  let d = parseInt(match[1]);
  let m = parseInt(match[2]) - 1;
  let y = parseInt(match[3]);

  return new Date(y, m, d);
}

/* =========================
   CHECK DAYS
========================= */

function isWithinDays(date, days = 7) {

  if (!date) return false;

  let today = new Date();
  today.setHours(0,0,0,0);

  let diff = (date - today) / (1000 * 60 * 60 * 24);

  return diff >= 0 && diff <= days;
}

/* =========================
   SIDEBAR DEADLINE
========================= */

(function(){

  const el = document.getElementById("sidebarDeadline");

  if(!el) return;

  const cb = "deadline_" + Date.now();

  window[cb] = function(d){

    let h = "";
    let count = 0;

    if(!d.feed || !d.feed.entry){
      el.innerHTML = "<li>No updates</li>";
      return;
    }

    (d.feed.entry || []).forEach(p=>{

      let l = p.link.find(x=>x.rel==="alternate").href;

      let lastDate = getLastDateObj(p);

      if(!lastDate) return;

      if(isWithinDays(lastDate,7)){

        let last = lastDate.toLocaleDateString("en-GB");

        let title = p.title.$t.substring(0,70);

        h += `
        <li>
          <a href="${l}">🔺 ${title}</a>
          <br>
          <span class="deadlineDate">
            Last Date: ${last}
          </span>
        </li>`;

        count++;
      }

    });

    if(count===0){
      h = "<li>No urgent jobs</li>";
    }

    el.innerHTML = h;

  };

  loadFeed(
    `${blogUrl}/feeds/posts/default/-/RECRUITMENT?alt=json-in-script`,
    cb
  );

})();

/* =========================
   TRENDING JOBS
========================= */

(function(){

  const el = document.getElementById("sidebarTrending");

  if(!el) return;

  const cb = "trend_" + Date.now();

  window[cb] = function(d){

    let arr = [];

    (d.feed.entry || []).forEach(p=>{

      arr.push({
        title:p.title.$t,
        link:p.link.find(x=>x.rel==="alternate").href,
        score:Math.random()*100
      });

    });

    arr.sort((a,b)=>b.score-a.score);

    let h = "";

    arr.slice(0,5).forEach(p=>{

      h += `
      <li>
        <a href="${p.link}">
          ☛ ${p.title}
        </a>
      </li>`;

    });

    el.innerHTML = h;

  };

  loadFeed(
    `${blogUrl}/feeds/posts/default/-/RECRUITMENT?alt=json-in-script`,
    cb
  );

})();

/* =========================
   FRESH UPDATES
========================= */

(function(){

  const el = document.getElementById("sidebarUpdates");

  if(!el) return;

  function isUpdate(post){

    let categories = post.category || [];

    return categories.some(c=>{

      let label = c.term.toLowerCase();

      return (
        label.includes("result") ||
        label.includes("admit")
      );

    });

  }

  const cb = "updates_" + Date.now();

  window[cb] = function(d){

    let h = "";
    let count = 0;

    (d.feed.entry || []).forEach(p=>{

      if(isUpdate(p) && count < 5){

        let l = p.link.find(x=>x.rel==="alternate").href;

        h += `
        <li>
          <a href="${l}">
            ➣ ${p.title.$t}
          </a>
        </li>`;

        count++;

      }

    });

    el.innerHTML = h || "<li>No updates</li>";

  };

  loadFeed(
    `${blogUrl}/feeds/posts/default?alt=json-in-script`,
    cb
  );

})();

